	for _, p := range reviewEnvPrefixes {
		if strings.HasPrefix(kv, p) {
			return true
		}
	}
	for _, p := range investigateEnvPrefixes {
		if strings.HasPrefix(kv, p) {
			return true
		}
	}
	return false
}

