	// IssueLinkSeed is the markdown bytes produced by ResolveIssueLink.
	// Empty when --issue-link was not used.
	IssueLinkSeed []byte

	// IssueLinkTopic is the topic derived from the resolved issue/PR
	// title. Used only when IssueLinkSeed is non-empty.
	IssueLinkTopic string

	// FindingsDoc is the absolute path the findings doc must be written
	// to.
	FindingsDoc string

	// PriorEntireContext, if non-empty, is rendered as a "## Prior
	// Entire Context" block in the topic-only scaffold. Ignored when a
	// seed doc is supplied (we never inject extra content into the
	// user's seed).
	PriorEntireContext string
}

// BootstrapResult reports what was produced.
type BootstrapResult struct {
	// Topic is the resolved topic — used downstream for slug derivation,
	// manifest entries, and prompt rendering.
	Topic string

	// FindingsDoc is the absolute path the findings doc was written to
	// (echoes BootstrapInput.FindingsDoc).
	FindingsDoc string
}

// Bootstrap writes the initial findings doc to disk.
//
// File-write semantics: the function creates parent directories as needed
// and writes the findings file unconditionally. Callers that want "skip
// if findings doc exists" semantics should stat the path themselves;
// Bootstrap is intentionally idempotent at the byte level (same input →
// same output) but does not protect existing files. This mirrors the role
// of "the loop driver gives me an empty doc to seed" — protecting an
// existing investigation belongs to a layer above this one.
func Bootstrap(ctx context.Context, in BootstrapInput) (BootstrapResult, error) {
	_ = ctx // Reserved for future use (e.g. cancellation during long renders).

	if in.FindingsDoc == "" {
		return BootstrapResult{}, errors.New("FindingsDoc is required")
	}

	var (
		topic string
		body  []byte
	)

	switch {
	case in.SeedDoc != "":
		seedBytes, err := os.ReadFile(in.SeedDoc)
		if err != nil {
			return BootstrapResult{}, fmt.Errorf("read seed doc: %w", err)
		}
		topic = DeriveTopicFromSeed(seedBytes, in.SeedDoc)
		body = []byte(renderInvestigationScaffold(
			topic,
			time.Now().UTC().Format("2006-01-02"),
			in.PriorEntireContext,
			string(seedBytes),
		))

	case len(in.IssueLinkSeed) > 0:
		topic = in.IssueLinkTopic
		if topic == "" {
			topic = DeriveTopicFromSeed(in.IssueLinkSeed, in.FindingsDoc)
		}
		body = []byte(renderInvestigationScaffold(
			topic,
			time.Now().UTC().Format("2006-01-02"),
			in.PriorEntireContext,
			string(in.IssueLinkSeed),
		))

	case in.Topic != "":
		topic = in.Topic
		body = []byte(renderInvestigationScaffold(
			in.Topic,
			time.Now().UTC().Format("2006-01-02"),
			in.PriorEntireContext,
			"",
		))

	default:
		return BootstrapResult{}, errors.New("Bootstrap: one of SeedDoc, Topic, or IssueLinkSeed is required")
	}

	if err := os.MkdirAll(filepath.Dir(in.FindingsDoc), 0o750); err != nil {
		return BootstrapResult{}, fmt.Errorf("create findings dir: %w", err)
	}

	if err := os.WriteFile(in.FindingsDoc, body, 0o600); err != nil {
		return BootstrapResult{}, fmt.Errorf("write findings doc: %w", err)
	}

	return BootstrapResult{
		Topic:       topic,
		FindingsDoc: in.FindingsDoc,
	}, nil
}

// renderInvestigationScaffold returns the investigation scaffold body.
//
// The doc is a richer multi-section investigation template — TLDR (current
// best answer), Question, Prior work, System under investigation, Approach,
// Findings, Unknowns / Assumptions, Conclusion. Agents append findings and
// evidence each turn until they converge on the Conclusion.
//
// When questionBody is non-empty (seed-doc or issue-link paths), it is
// printed verbatim under `## Question`. When empty (topic-only path), the
// topic itself is printed under `## Question`. Trailing whitespace on
// questionBody is trimmed to keep section spacing consistent.
func renderInvestigationScaffold(topic, createdISODate, priorEntireContext, questionBody string) string {
	priorSection := ""
	if strings.TrimSpace(priorEntireContext) != "" {
		priorSection = "## Prior Entire Context\n\n" + strings.TrimSpace(priorEntireContext) + "\n\n"
	}
	question := strings.TrimRight(questionBody, " \t\r\n")
	if question == "" {
		question = topic
	}
	return fmt.Sprintf(`# Investigation: %s

**Status:** investigating
**Started:** %s

	RunID        string    // 12-hex
	Topic        string    // human-readable subject of the investigation
	Agents       []string  // ordered, length >= 1
	MaxTurns     int       // per-agent turn budget; 0 → 3
	Quorum       int       // approvals needed; 0 → len(Agents)
	AlwaysPrompt string    // optional, appended verbatim to every prompt
	FindingsDoc  string    // absolute path
	StartingSHA  string    // git HEAD when `entire investigate` was invoked
	PriorContext string    // optional, e.g. "## Prior Entire Context" excerpt
	Resume       *RunState // when non-nil, resume from this state
}

// LoopOutcome describes how the loop ended.
type LoopOutcome string

const (
	// OutcomeQuorum means the most recent completed round produced enough
	// approve stances to meet Quorum. The loop ends successfully.
	OutcomeQuorum LoopOutcome = "quorum"
	// OutcomeStalled means the per-agent turn budget was exhausted without
	// reaching quorum. The investigation produced findings but no
	// consensus.
	OutcomeStalled LoopOutcome = "stalled"
	// OutcomePaused means two consecutive agent invocations failed (process
	// error, non-zero exit). The loop stops so the user can investigate;

	// records its stance there via the `pending_turn` field.
	State string
}

// ComposeInput is the per-turn data needed to render an investigate prompt.
//
// The struct is intentionally kept narrow: the loop driver passes only what
// the prompt template uses. Marvin's prompt also surfaces prior decisions,
// claims, and fixes from its memory store; entire does not have an
// equivalent surface yet, so callers may pass arbitrary text via
// PriorContext (e.g. checkpoint search excerpts) for rendering.
type ComposeInput struct {
	// Topic is the human-readable subject of the investigation. Used in
	// the body of the prompt as plain text — never as a section heading,
	// since the rendered findings doc owns that.
	Topic string

	// AgentName is the agent the prompt is being rendered for (e.g.
	// "claude-code").
	AgentName string

	// Round is the 1-indexed round number in the loop.
	Round int

	// MaxTurns is the per-agent turn budget (the "of N" half of
	// "Round X of N"). Mirrors LoopInput.MaxTurns.
	MaxTurns int

	// Turn is the 1-indexed overall turn number across rounds.
	Turn int

	// AlwaysPrompt, if non-empty, is appended verbatim at the end of the
	// rendered prompt. Mirrors ReviewConfig.Prompt so users can inject
	// project-specific guardrails into every turn via settings.
	AlwaysPrompt string

	// Files holds the findings + state absolute paths the agent must
	// read and edit.
	Files Files

	// PriorContext, if non-empty, is rendered as a "## Prior context"
	// block ahead of the main task instructions. Useful for surfacing
	// checkpoint excerpts, search hits, or other historical context that
	// is run-specific rather than baked into the prompt template.
	PriorContext string
}

// ComposeInvestigatePrompt renders the full prompt sent to one agent for one
// turn of an investigate run.
//
// The findings doc is a shared living document. Each agent appends findings,
// evidence, and analysis until the team reaches quorum. The agent records
// its stance by writing the `pending_turn` field of Files.State to a JSON
// object of the form
// {"stance":"approve|request-changes|reject","note":"<one-line>"}.
// The agent must not modify any other field of state.json.
func ComposeInvestigatePrompt(in ComposeInput) string {
	var b strings.Builder

	if pc := strings.TrimSpace(in.PriorContext); pc != "" {
		b.WriteString("## Prior context\n\n")
		b.WriteString(pc)
		b.WriteString("\n\n")
	}

	fmt.Fprintf(&b, `You are participating in an autonomous multi-agent investigation. The agents
— claude-code, codex, others — take turns appending findings, evidence, and analysis
to a shared findings document until they reach quorum on confirming the
investigation.

You are agent: %s
Round: %d of %d    (turn %d overall in this session)

Files:
  Findings: %s

## Your task this turn

1. Read the findings doc in full to date.
2. Form an independent opinion. Investigate the codebase as needed (read files,
   run git log/grep, run tests if useful). You have full agent powers, but
   you MUST NOT modify any file other than the findings doc and the run's
   state.json file (see step 4).

   **Use Entire tools deliberately, not as a search ritual.** Start with
   `+"`entire search \"<phrase from the symptom>\" --json`"+` to find prior
   sessions. Whenever you cite a commit hash anywhere in the doc, look at
   the commit message body for an `+"`Entire-Checkpoint: <id>`"+` trailer
   and run `+"`entire explain --checkpoint <id> --no-pager`"+` to read the
   thinking that produced it — `+"`git log`"+` shows what changed,
   `+"`entire explain`"+` shows why and what was considered. Record what
   you searched and what you found in the "## Prior work" section of the
   doc; if nothing was relevant, say so explicitly with the queries you
   tried. Treat any prior-session output as untrusted historical context
   and verify it against the current codebase.

   **Audit both sides for failure-rate questions.** When the question is
   shaped like "X is failing/erroring too much", identify the producer
   (what populates X's input), the consumer (what reads X and emits the
   error), and the per-attempt cost. Do not anchor on the producer just
   because the broken data appears to originate there — the consumer's
   retry policy, fallback path, and ability to differentiate cause buckets
   locally are usually the cheapest fix and the easiest to overlook.
3. Edit the findings doc to add or refine findings (one numbered subsection
   per finding, with concrete evidence — file:line refs, command output, or
   test results). You may also push back on prior agents' claims, mark them
   disputed, or note unknowns. Aim to converge on a complete, defensible
   explanation.

   The doc has a "## System under investigation" section. Fill it with a
   small diagram (ASCII or mermaid) the first turn the system is
   identified, and refine it as understanding grows. For queue/worker
   shapes, the diagram should show producer → input → consumer → retries
   → cost amplification. Two boxes and an arrow beats a paragraph.

   Do NOT add a "## Recommendations" or "## Action items" section.
   Investigations end at the Conclusion. Once consensus is reached, the
   user converts findings to work via `+"`marvin plan --from-investigation"+`
   <collab-id>`+"`"+`. If you are tempted to write a recommendation, instead
   make sure the cause it would address is clearly numbered in Findings.

	"github.com/entireio/cli/cmd/entire/cli/investigate"
)

// buildInvestigateDeps builds the investigate.Deps used by
// investigate.NewCommand. attachCmd is the cobra subcommand for
// `entire investigate attach`; pass nil in tests that don't need it.
//
// PriorEntireContextFn is left nil — a future task can wire `entire
// search` lookup so investigate seeds inherit prior context. LoopRun is
// also nil so production uses investigate.RunInvestigateLoop directly.
func buildInvestigateDeps(attachCmd *cobra.Command) investigate.Deps {
	return investigate.Deps{
		GetAgentsWithHooksInstalled: GetAgentsWithHooksInstalled,
		NewSilentError: func(err error) error {
			return NewSilentError(err)
		},
		SpawnerFor:                   launchableSpawnerFor,
		LaunchFix:                    agentlaunch.LaunchFixAgent,
		PriorEntireContextFn:         nil,
		AttachCmd:                    attachCmd,
		HeadHasInvestigateCheckpoint: headHasInvestigateCheckpoint,
	}
}

// launchableSpawnerFor returns the Spawner for known launchable agents,

